import React from "react";
import { T, FZ } from "../theme";
import { typedMentions, toggleToken, mailtoFor } from "../mentions";
import { useMentions } from "../mentionContext";

// Puces « @ Prénom Nom » pour taguer un manager dans un commentaire + case « Prévenir par e-mail » (message préparé dans la messagerie).
// Utilisé dans la fiche Manager, la fenêtre projet et la page Commentaires.
export function MentionPicker({ text, setText, notify, setNotify, options }) {
  const ctx = useMentions();
  const opts = options || ctx.options;
  if (!opts || !opts.length) return null;
  const tagged = typedMentions(text, opts);
  const others = tagged.filter(o => o.email !== ctx.me);
  return (<div style={{ display: "flex", flexDirection: "column", gap: 4, marginTop: 6 }}>
    <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
      <span style={{ fontSize: FZ.xs, fontWeight: 700, color: T.ink500 }}>Taguer :</span>
      {opts.map(o => { const on = tagged.some(x => x.email === o.email); return (<button key={o.email} type="button" aria-pressed={on} title={o.email} onClick={() => setText(t => toggleToken(t, o))}
        style={{ border: "1px solid " + (on ? T.violet500 : T.line), background: on ? T.violet100 : "transparent", color: on ? T.violet600 : T.ink700, borderRadius: 999, padding: "2px 9px", fontSize: FZ.xs, fontWeight: 700, cursor: "pointer", fontFamily: T.font }}>{on ? "✓ " : "@ "}{o.name}</button>); })}
    </div>
    {tagged.length > 0 && <div style={{ fontSize: FZ.xs, color: T.violet600 }}>{tagged.map(o => o.name).join(", ")} {tagged.length > 1 ? "verront" : "verra"} cette demande dans sa cloche de notifications et pourr{tagged.length > 1 ? "ont" : "a"} la marquer « traitée ».</div>}
    {others.length > 0 && setNotify && <label style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: FZ.xs, fontWeight: 600, color: T.ink500, cursor: "pointer" }}>
      <input type="checkbox" checked={!!notify} onChange={e => setNotify(e.target.checked)} />Prévenir aussi par e-mail (ouvre un message prêt à envoyer)
    </label>}
  </div>);
}

// À appeler après un commentaire publié avec succès, si la case « Prévenir par e-mail » était cochée.
export function mailTagged(options, me, text, info) {
  const href = mailtoFor(typedMentions(text, options), { ...info, text, me, url: typeof window !== "undefined" ? window.location.origin + window.location.pathname : "" });
  if (href && typeof window !== "undefined") window.location.href = href;
}
